-- First verified snapshot of the Senegal higher-education catalogue (2026-11-11).
-- 94 Campusen institutions and 1,171 validated formations, plus 5 institutions and 50
-- formations from the Campusen orientation feed. Internal components are stored on programmes.
-- Three official UGB curricula supply 274 course entries and one additional programme.
-- ANAQ-Sup/CAMES links require a unique institution and diploma match, retain source
-- references and cover only decisions from 2022 through 2026. Years have year precision.
-- MESRI school tags document the presence of an act. Its scope and reference are stored below.
-- This is an additive snapshot. Run it as one Flyway transaction, without network access.

ALTER TABLE schools
    ALTER COLUMN name TYPE varchar(255),
    ADD COLUMN campusen_id integer UNIQUE,
    ADD COLUMN source_url text,
    ADD COLUMN source_name text;
ALTER TABLE programs
    ALTER COLUMN name TYPE varchar(255),
    ADD COLUMN campusen_id integer UNIQUE,
    ADD COLUMN source_url text,
    ADD COLUMN source_name text,
    ADD COLUMN source_reference text,
    ADD COLUMN source_component text;
ALTER TABLE courses
    ALTER COLUMN name TYPE varchar(255),
    ADD COLUMN source_url text;
ALTER TABLE accreditations ALTER COLUMN name TYPE varchar(255);
ALTER TABLE program_accreditations
    ADD COLUMN source_url text,
    ADD COLUMN source_reference text,
    ADD COLUMN source_name text;

CREATE TABLE school_habilitations (
    school_id integer NOT NULL REFERENCES schools (id) ON DELETE CASCADE,
    reference text NOT NULL,
    issued_year integer NOT NULL,
    source_url text NOT NULL,
    printed_page integer,
    scope text NOT NULL,
    programs_covered text NOT NULL,
    PRIMARY KEY (school_id, reference)
);

CREATE TEMP TABLE seed_schools (
    seed_id integer PRIMARY KEY,
    name text NOT NULL,
    source_name text NOT NULL,
    legacy_code text,
    city text,
    tag text,
    url text NOT NULL,
    target_id integer UNIQUE
) ON COMMIT DROP;

CREATE TEMP TABLE seed_programs (
    seed_id integer PRIMARY KEY,
    school_seed_id integer NOT NULL REFERENCES seed_schools (seed_id),
    campusen_id integer UNIQUE,
    name text NOT NULL,
    source_name text NOT NULL,
    level text,
    reference text,
    component text NOT NULL,
    url text NOT NULL,
    target_id integer UNIQUE
) ON COMMIT DROP;

CREATE TEMP TABLE seed_courses (
    program_seed_id integer NOT NULL REFERENCES seed_programs (seed_id),
    name text NOT NULL,
    curriculum_details text NOT NULL,
    url text NOT NULL,
    PRIMARY KEY (program_seed_id, name)
) ON COMMIT DROP;

CREATE TEMP TABLE seed_accreditations (
    program_seed_id integer NOT NULL REFERENCES seed_programs (seed_id),
    code text NOT NULL,
    starts integer NOT NULL,
    ends integer NOT NULL,
    url text NOT NULL,
    reference text NOT NULL,
    source_name text NOT NULL,
    PRIMARY KEY (program_seed_id, code)
) ON COMMIT DROP;

CREATE TEMP TABLE seed_habilitations (
    school_seed_id integer NOT NULL REFERENCES seed_schools (seed_id),
    issued_year integer NOT NULL,
    reference text NOT NULL,
    url text NOT NULL,
    printed_page integer,
    scope text NOT NULL,
    programs_covered text NOT NULL,
    PRIMARY KEY (school_seed_id, reference)
) ON COMMIT DROP;





