-- Match normalized official or established display names within Senegal. Never use an acronym
-- alone to bind a previously edited school to a decision from the source registers.
CREATE FUNCTION pg_temp.catalogue_name_key(value text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT AS $$
    SELECT regexp_replace(
        replace(translate(lower(value), 'àâäéèêëîïôöùûüçÿ', 'aaaeeeeiioouuucy'), 'œ', 'oe'),
        '[^a-z0-9]+', '', 'g'
    );
$$;

CREATE TEMP TABLE school_matches ON COMMIT DROP AS
SELECT seed.seed_id, school.id,
       count(*) OVER (PARTITION BY seed.seed_id) AS schools_per_seed,
       count(*) OVER (PARTITION BY school.id) AS seeds_per_school
FROM seed_schools seed
JOIN schools school ON pg_temp.catalogue_name_key(school.name) IN (
    pg_temp.catalogue_name_key(seed.name), pg_temp.catalogue_name_key(seed.source_name)
)
WHERE nullif(pg_temp.catalogue_name_key(school.country), '') IS NULL
   OR pg_temp.catalogue_name_key(school.country) IN ('senegal', 'sn');

UPDATE seed_schools seed
SET target_id = match.id
FROM school_matches match
WHERE match.seed_id = seed.seed_id AND match.schools_per_seed = 1 AND match.seeds_per_school = 1;

-- Hold ambiguous matches for a later reconciliation. Preserve all existing editable fields.
UPDATE schools school
SET campusen_id = CASE WHEN seed.seed_id > 0 THEN seed.seed_id END,
    source_url = seed.url, source_name = seed.source_name
FROM seed_schools seed
WHERE school.id = seed.target_id;

WITH new_schools AS (
    SELECT seed.name,
           CASE WHEN NOT EXISTS (SELECT 1 FROM schools WHERE upper(code) = upper(seed.legacy_code))
               THEN seed.legacy_code END,
           seed.city, 'Sénégal', CASE WHEN seed.seed_id > 0 THEN seed.seed_id END,
           seed.url, seed.source_name, current_timestamp, current_timestamp
    FROM seed_schools seed
    WHERE seed.target_id IS NULL AND NOT EXISTS (
        SELECT 1 FROM school_matches match WHERE match.seed_id = seed.seed_id
    )
    RETURNING id, name, campusen_id, source_url
)
UPDATE seed_schools seed
SET target_id = school.id
FROM new_schools school
WHERE seed.seed_id = school.campusen_id
   OR (seed.seed_id < 0 AND seed.name = school.name AND seed.url = school.source_url);

CREATE TEMP TABLE program_matches ON COMMIT DROP AS
SELECT seed.seed_id, program.id,
       count(*) OVER (PARTITION BY seed.seed_id) AS programs_per_seed,
       count(*) OVER (PARTITION BY program.id) AS seeds_per_program
FROM seed_programs seed
JOIN seed_schools school ON school.seed_id = seed.school_seed_id
JOIN programs program ON program.school_id = school.target_id AND (
    pg_temp.catalogue_name_key(program.name) = pg_temp.catalogue_name_key(seed.name)
    OR (program.level = seed.level
        AND pg_temp.catalogue_name_key(program.name) = pg_temp.catalogue_name_key(seed.source_name))
);

UPDATE seed_programs seed
SET target_id = match.id
FROM program_matches match
WHERE match.seed_id = seed.seed_id AND match.programs_per_seed = 1 AND match.seeds_per_program = 1;

UPDATE programs program
SET campusen_id = seed.campusen_id, source_url = seed.url, source_name = seed.source_name,
    source_reference = seed.reference, source_component = seed.component
FROM seed_programs seed
WHERE program.id = seed.target_id;

WITH new_programs AS (
                          source_component, created_at, modified_at)
    SELECT school.target_id, seed.name, seed.level, seed.campusen_id, seed.url, seed.source_name, seed.reference,
           seed.component, current_timestamp, current_timestamp
    FROM seed_programs seed
    JOIN seed_schools school ON school.seed_id = seed.school_seed_id AND school.target_id IS NOT NULL
    WHERE seed.target_id IS NULL AND NOT EXISTS (
        SELECT 1 FROM program_matches match WHERE match.seed_id = seed.seed_id
    )
    RETURNING id, school_id, name, campusen_id, source_url
)
UPDATE seed_programs seed
SET target_id = program.id
FROM new_programs program, seed_schools school
WHERE school.seed_id = seed.school_seed_id AND school.target_id = program.school_id
  AND (seed.campusen_id = program.campusen_id
       OR (seed.campusen_id IS NULL AND seed.name = program.name AND seed.url = program.source_url));

-- Keep existing course descriptions and IDs. Attach source metadata only to an unambiguous match.
WITH course_matches AS (
    SELECT course.id, seed.url,
           count(*) OVER (PARTITION BY seed.program_seed_id, seed.name) AS courses_per_seed,
           count(*) OVER (PARTITION BY course.id) AS seeds_per_course
    FROM seed_courses seed
    JOIN seed_programs program ON program.seed_id = seed.program_seed_id
    JOIN courses course ON course.program_id = program.target_id
        AND pg_temp.catalogue_name_key(course.name) = pg_temp.catalogue_name_key(seed.name)
)
UPDATE courses course
SET source_url = match.url
FROM course_matches match
WHERE course.id = match.id AND match.courses_per_seed = 1 AND match.seeds_per_course = 1;

SELECT program.target_id, seed.name, seed.curriculum_details, seed.url, current_timestamp, current_timestamp
FROM seed_courses seed
JOIN seed_programs program ON program.seed_id = seed.program_seed_id AND program.target_id IS NOT NULL
WHERE NOT EXISTS (
    SELECT 1 FROM courses course WHERE course.program_id = program.target_id
      AND pg_temp.catalogue_name_key(course.name) = pg_temp.catalogue_name_key(seed.name)
);

SELECT seed.code, seed.name, seed.description, current_timestamp, current_timestamp
FROM (VALUES
    ('ANAQ', 'ANAQ-Sup', 'Accréditation de programme de l’Autorité nationale d’assurance qualité du Sénégal'),
    ('CAMES', 'CAMES', 'Reconnaissance de diplôme du Conseil africain et malgache pour l’enseignement supérieur (PRED)')
) AS seed(code, name, description)
WHERE NOT EXISTS (SELECT 1 FROM accreditations accreditation WHERE upper(accreditation.code) = seed.code);

WITH unique_accreditations AS (
    SELECT upper(code) AS code, min(id) AS id
    FROM accreditations
    WHERE upper(code) IN ('ANAQ', 'CAMES')
    GROUP BY upper(code)
    HAVING count(*) = 1
)
SELECT program.target_id, accreditation.id, seed.starts, seed.ends, seed.url, seed.reference, seed.source_name
FROM seed_accreditations seed
JOIN seed_programs program ON program.seed_id = seed.program_seed_id AND program.target_id IS NOT NULL
JOIN unique_accreditations accreditation ON accreditation.code = seed.code
ON CONFLICT (accreditation_id, program_id) DO NOTHING;

SELECT school.target_id, seed.reference, seed.issued_year, seed.url, seed.printed_page, seed.scope, seed.programs_covered
FROM seed_habilitations seed
JOIN seed_schools school ON school.seed_id = seed.school_seed_id AND school.target_id IS NOT NULL;

WITH labels AS (
    SELECT DISTINCT tag AS name FROM seed_schools WHERE tag IS NOT NULL
    UNION SELECT 'Habilitation MESRI documentée'
)
SELECT name, current_timestamp, current_timestamp FROM labels
ON CONFLICT (name) DO NOTHING;

WITH school_labels AS (
    SELECT target_id AS school_id, tag AS name FROM seed_schools WHERE target_id IS NOT NULL AND tag IS NOT NULL
    UNION
    SELECT school_id, 'Habilitation MESRI documentée' FROM school_habilitations
)
SELECT label.school_id, tag.id
FROM school_labels label JOIN tags tag ON tag.name = label.name
ON CONFLICT (school_id, tag_id) DO NOTHING;

DROP FUNCTION pg_temp.catalogue_name_key(text);
